import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int length = inputStr.length();
        StringBuilder outputStr = new StringBuilder();
        boolean foundAtSymbol = false;

        // Check if '@' exists in the input
        for (int i = 0; i < length; i++) {
            if (inputStr.charAt(i) == '@') {
                foundAtSymbol = true;
                break;
            }
        }

        char[] chars = inputStr.toCharArray();

        for (int i = 0; i < length; i++) {
            if (i + 2 < length && chars[i] == 'd' && chars[i + 1] == 'o' && chars[i + 2] == 't' && i != 0 && i != length - 3) {
                outputStr.append('.');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                chars[i + 2] = ' ';
            }
            if (i + 1 < length && chars[i] == 'a' && chars[i + 1] == 't' && i != 0 && i != length - 2 && !foundAtSymbol) {
                outputStr.append('@');
                chars[i] = ' ';
                chars[i + 1] = ' ';
                foundAtSymbol = true;
            } else if (chars[i] != ' ') {
                outputStr.append(chars[i]);
            }
        }
        System.out.println(outputStr.toString());
        scanner.close();
    }
}
